/// The Unicode simple case-fold orbit of `c` (including `c`), or `None` if `c`
/// has no case-fold mates. Used for `(?i)` matching in Unicode mode.
pub fn orbit(c: char) -> Option<&'static [char]> {
    let cp = c as u32;
    match ORBIT_INDEX.binary_search_by(|&(k, _)| k.cmp(&cp)) {
        Ok(i) => Some(ORBITS[ORBIT_INDEX[i].1 as usize]),
        Err(_) => None,
    }
}

/// Whether `a` and `b` are equal under Unicode simple case folding.
pub fn fold_eq(a: char, b: char) -> bool {
    a == b || orbit(a).is_some_and(|o| o.contains(&b))
}
